contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry performing the property-based test
    // donateAmount: amount to forward to c.donate()
    function run(uint256 donateAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donateAmount)); require(donateAmount <= 1000000000000000000000000000000);
        // ensure this test contract can send the requested Ether
        require(address(this).balance >= donateAmount);

        // make contract open to public (this contract is the owner because it deployed C)
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // read observables before
        uint256 beforeBalance = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // perform the donate call and capture revert
        bool reverted;
        c.donate{value: donateAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observables after
        uint256 afterBalance = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // General rule:
        // If donate reverted then nothing observable about c changed.
        // If it succeeded then contract balance cannot increase (it should forward funds to whale),
        // and winnersPot (which is address(c).balance / 2) cannot have increased either.
        assert((reverted && afterBalance == beforeBalance && afterWinnersPot == beforeWinnersPot) || (!reverted && afterBalance <= beforeBalance && afterWinnersPot <= beforeWinnersPot));
    }

    // allow receiving refunds etc.
    receive() external payable {}
}

