// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 donateAmount) internal {
        donateAmount = bound(donateAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= donateAmount);
        try c.OpenToThePublic() {} catch { return; }
        uint256 beforeBalance = address(c).balance;
        uint256 beforeWinnersPot;
        try c.winnersPot() returns (uint256 __r) { beforeWinnersPot = __r; } catch { return; }
        bool reverted;
        try c.donate{value: donateAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 afterWinnersPot;
        try c.winnersPot() returns (uint256 __r) { afterWinnersPot = __r; } catch { return; }
        assertTrue((reverted && afterBalance == beforeBalance && afterWinnersPot == beforeWinnersPot) || (!reverted && afterBalance <= beforeBalance && afterWinnersPot <= beforeWinnersPot));
    }

    function testFuzz_run(uint256 donateAmount) public {
        _run(donateAmount);
    }

    receive() external payable {}
}
